export const importedVocabulary=[{"term": "Scarcity", "definition": "The condition in which limited resources cannot satisfy unlimited wants, making choices necessary.", "topic": null, "zh": null}, {"term": "Factors of Production", "definition": "The resources used to produce goods and services: land, labor, capital, and entrepreneurship.", "topic": "1.1", "zh": "生产要素"}, {"term": "Opportunity Cost", "definition": "The value of the next-best alternative given up when a choice is made.", "topic": null, "zh": null}, {"term": "Trade-Off", "definition": "An alternative use of scarce resources that must be sacrificed when choosing another option.", "topic": null, "zh": null}, {"term": "Economic System", "definition": "The way a society answers what to produce, how to produce, and for whom to produce.", "topic": "1.2", "zh": "经济制度"}, {"term": "Market Economy", "definition": "An economic system in which prices and voluntary exchange guide resource allocation.", "topic": null, "zh": null}, {"term": "Command Economy", "definition": "An economic system in which government planners make most allocation decisions.", "topic": null, "zh": null}, {"term": "Production Possibilities Curve", "definition": "A model showing combinations of two goods an economy can produce with available resources and technology.", "topic": null, "zh": null}, {"term": "Productive Efficiency", "definition": "Producing the maximum possible output from available resources with no avoidable waste.", "topic": null, "zh": null}, {"term": "Law of Increasing Opportunity Cost", "definition": "As more of one good is produced, the opportunity cost of producing it rises.", "topic": "1.3", "zh": "机会成本递增规律"}, {"term": "Absolute Advantage", "definition": "The ability to produce more output with the same resources than another producer.", "topic": null, "zh": null}, {"term": "Comparative Advantage", "definition": "The ability to produce a good or service at a lower opportunity cost than another producer.", "topic": null, "zh": null}, {"term": "Specialization and Trade", "definition": "Focusing on production according to comparative advantage and exchanging for other goods.", "topic": "1.4", "zh": "专业化与贸易"}, {"term": "Marginal Analysis", "definition": "Decision-making that compares the additional benefit and additional cost of one more unit of an action.", "topic": "1.6", "zh": "边际分析"}, {"term": "Utility", "definition": "The satisfaction or usefulness a consumer receives from consuming goods or services.", "topic": null, "zh": null}, {"term": "Marginal Utility", "definition": "The additional satisfaction gained from consuming one more unit.", "topic": null, "zh": null}, {"term": "Diminishing Marginal Utility", "definition": "The principle that each additional unit consumed usually adds less extra satisfaction than the previous unit.", "topic": null, "zh": null}, {"term": "Consumer Optimization", "definition": "Choosing the combination of goods that maximizes total utility within a budget.", "topic": "1.6", "zh": "消费者最优化"}, {"term": "Demand", "definition": "The willingness and ability of consumers to buy quantities of a good at different prices.", "topic": null, "zh": null}, {"term": "Quantity Demanded", "definition": "The amount consumers are willing and able to buy at one specific price.", "topic": null, "zh": null}, {"term": "Law of Demand", "definition": "Price and quantity demanded move in opposite directions, all else equal.", "topic": "2.1", "zh": "需求定律"}, {"term": "Demand Shifter", "definition": "A non-price factor that changes demand, such as income, tastes, expectations, buyers, or related-good prices.", "topic": "2.1", "zh": "需求移动因素"}, {"term": "Normal Good", "definition": "A good whose demand increases when consumer income rises.", "topic": null, "zh": null}, {"term": "Inferior Good", "definition": "A good whose demand decreases when consumer income rises.", "topic": null, "zh": null}, {"term": "Substitutes", "definition": "Goods that can be used in place of each other; a higher price for one raises demand for the other.", "topic": null, "zh": null}, {"term": "Complements", "definition": "Goods used together; a higher price for one lowers demand for the other.", "topic": null, "zh": null}, {"term": "Supply", "definition": "The willingness and ability of producers to sell quantities of a good at different prices.", "topic": null, "zh": null}, {"term": "Quantity Supplied", "definition": "The amount producers are willing and able to sell at one specific price.", "topic": null, "zh": null}, {"term": "Law of Supply", "definition": "Price and quantity supplied move in the same direction, all else equal.", "topic": "2.2", "zh": "供给定律"}, {"term": "Supply Shifter", "definition": "A non-price factor that changes supply, such as input prices, technology, taxes, subsidies, expectations, or number of sellers.", "topic": "2.2", "zh": "供给移动因素"}, {"term": "Equilibrium", "definition": "The price and quantity where quantity demanded equals quantity supplied.", "topic": null, "zh": null}, {"term": "Shortage", "definition": "A disequilibrium condition in which quantity demanded exceeds quantity supplied.", "topic": null, "zh": null}, {"term": "Surplus", "definition": "A disequilibrium condition in which quantity supplied exceeds quantity demanded.", "topic": null, "zh": null}, {"term": "Consumer Surplus", "definition": "The difference between what buyers are willing to pay and what they actually pay.", "topic": null, "zh": null}, {"term": "Producer Surplus", "definition": "The difference between the price sellers receive and the minimum price they would accept.", "topic": null, "zh": null}, {"term": "Deadweight Loss", "definition": "Lost total surplus caused by producing less or more than the efficient quantity.", "topic": null, "zh": null}, {"term": "Price Elasticity of Demand", "definition": "A measure of how responsive quantity demanded is to a change in price.", "topic": null, "zh": null}, {"term": "Total Revenue Test", "definition": "A method for identifying demand elasticity by observing how total revenue changes when price changes.", "topic": "2.3", "zh": "总收益检验"}, {"term": "Price Elasticity of Supply", "definition": "A measure of how responsive quantity supplied is to a change in price.", "topic": null, "zh": null}, {"term": "Income Elasticity of Demand", "definition": "A measure of how responsive demand is to a change in consumer income.", "topic": "2.5", "zh": "需求收入弹性"}, {"term": "Cross-Price Elasticity", "definition": "A measure of how responsive demand for one good is to a price change in another good.", "topic": "2.5", "zh": "需求交叉价格弹性"}, {"term": "Price Ceiling", "definition": "A legal maximum price; if set below equilibrium, it creates a shortage.", "topic": null, "zh": null}, {"term": "Price Floor", "definition": "A legal minimum price; if set above equilibrium, it creates a surplus.", "topic": null, "zh": null}, {"term": "Excise Tax", "definition": "A per-unit tax that raises buyers' price, lowers sellers' net price, and reduces quantity.", "topic": "2.8", "zh": "消费税"}, {"term": "Subsidy", "definition": "A government payment that lowers effective cost and encourages more production or consumption.", "topic": null, "zh": null}, {"term": "World Price", "definition": "The price of a good determined in the international market.", "topic": null, "zh": null}, {"term": "Tariff", "definition": "A tax on imports that raises domestic price and creates government revenue and deadweight loss.", "topic": null, "zh": null}, {"term": "Quota", "definition": "A legal limit on the quantity of a good that may be imported.", "topic": "2.9", "zh": "进口配额"}];
export const importedQuestions=[{"id": "legacy-001", "topic": "1.1", "unit": 1, "stem": "Scarcity exists because", "options": [{"key": "A", "text": "Human wants exceed the capacity of the economy", "error": null}, {"key": "B", "text": "Suppliers of land and other natural resources are unlimited", "error": "C1"}, {"key": "C", "text": "Physical capital does not depreciate", "error": "C1"}, {"key": "D", "text": "Population and labor force growth are slowing", "error": "C1"}], "correct": "A", "explanation": "Identify scarcity as the universal problem created by unlimited wants and limited resources; choices require tradeoffs and opportunity costs.", "zh": "资源有限而需求无法全部满足，所以必须取舍。知识可以被多人同时使用。", "skill": "concept", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 1, "sourceSection": "1.1"}, {"id": "legacy-002", "topic": "1.1", "unit": 1, "stem": "The study of economics exists because people are confronted with the basic problem of", "options": [{"key": "A", "text": "elasticity", "error": "C1"}, {"key": "B", "text": "negative externality", "error": "C1"}, {"key": "C", "text": "scarcity", "error": null}, {"key": "D", "text": "overabundance", "error": "C1"}], "correct": "C", "explanation": "Identify scarcity as the universal problem created by unlimited wants and limited resources; choices require tradeoffs and opportunity costs.", "zh": "资源有限而需求无法全部满足，所以必须取舍。知识可以被多人同时使用。", "skill": "concept", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 2, "sourceSection": "1.1"}, {"id": "legacy-003", "topic": "1.1", "unit": 1, "stem": "The basic economic problem of all countries is the existence of", "options": [{"key": "A", "text": "tax increases and budget deficits", "error": "C1"}, {"key": "B", "text": "limited resources and unlimited wants", "error": null}, {"key": "C", "text": "unemployment and inflation", "error": "C1"}, {"key": "D", "text": "government and private industry", "error": "C1"}], "correct": "B", "explanation": "Identify scarcity as the universal problem created by unlimited wants and limited resources; choices require tradeoffs and opportunity costs.", "zh": "资源有限而需求无法全部满足，所以必须取舍。知识可以被多人同时使用。", "skill": "concept", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 3, "sourceSection": "1.1"}, {"id": "legacy-004", "topic": "1.1", "unit": 1, "stem": "Which of the following describes a factor of production that is not fully scarce and that can be used simultaneously in the production of more than one good?", "options": [{"key": "A", "text": "Machines that can produce both clothing and bedsheets", "error": "C1"}, {"key": "B", "text": "Unskilled labor needed to produce all goods", "error": "C1"}, {"key": "C", "text": "Basic knowledge that enhances the organization of all manufacturing assembly lines", "error": null}, {"key": "D", "text": "Land that is cultivated for two crops by more than one farmer", "error": "C1"}], "correct": "C", "explanation": "Established knowledge is non-rival: using the same idea in one factory need not prevent another factory from using it.", "zh": "资源有限而需求无法全部满足，所以必须取舍。知识可以被多人同时使用。", "skill": "concept", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 4, "sourceSection": "1.1"}, {"id": "legacy-005", "topic": "1.5", "unit": 1, "stem": "After graduating from high school, Gloria chose to go to college, while Omar chose to work full time. Which of the following best describes the opportunity costs for these decisions?", "options": [{"key": "A", "text": "Gloria’s opportunity cost includes the salary she could have earned if she had gone to work.", "error": null}, {"key": "B", "text": "Gloria’s opportunity cost is her living expenses while attending college.", "error": "C1"}, {"key": "C", "text": "Omar’s opportunity cost is the salary he will earn from working.", "error": "C1"}, {"key": "D", "text": "Omar’s opportunity cost is the tuition and expenses he would have paid for college.", "error": "C1"}], "correct": "A", "explanation": "Opportunity cost is the value of the next-best alternative forgone, including explicit costs and forgone earnings when relevant.", "zh": "经济成本包括显性支出与隐性机会成本；选择总净收益更高的方案。", "skill": "concept", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 5, "sourceSection": "1.1"}, {"id": "legacy-006", "topic": "1.3", "unit": 1, "stem": "Assume an economy is using all its available resources efficiently to produce only two goods, X and Y. As more of good X is produced, what happens to the production of good Y?", "options": [{"key": "A", "text": "The production of good Y also increases.", "error": "C1"}, {"key": "B", "text": "More resources will need to be devoted to producing good Y.", "error": "C1"}, {"key": "C", "text": "Less of good Y is produced as resources move from producing good Y to producing good X.", "error": null}, {"key": "D", "text": "The economy can only produce more of good X if there is more labor available.", "error": "C1"}], "correct": "C", "explanation": "Identify scarcity as the universal problem created by unlimited wants and limited resources; choices require tradeoffs and opportunity costs.", "zh": "先判断曲线形状与资源利用状态：增加产能移动 PPC，充分利用闲置资源只是靠近原曲线。", "skill": "concept", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 6, "sourceSection": "1.1"}, {"id": "legacy-007", "topic": "1.1", "unit": 1, "stem": "Assume an economy is producing efficiently on its PPC with fixed resources and technology. Which statement describes its trade-off?", "options": [{"key": "A", "text": "If more of one good is produced, less of another good must be produced.", "error": null}, {"key": "B", "text": "An economy can produce a limitless amount of all goods.", "error": "C1"}, {"key": "C", "text": "All individuals are able to satisfy their consumption desires.", "error": "C1"}, {"key": "D", "text": "Scarcity is eliminated by government provision of goods.", "error": "C1"}], "correct": "A", "explanation": "Identify scarcity as the universal problem created by unlimited wants and limited resources; choices require tradeoffs and opportunity costs.", "zh": "资源有限而需求无法全部满足，所以必须取舍。知识可以被多人同时使用。", "skill": "concept", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 7, "sourceSection": "1.1"}, {"id": "legacy-008", "topic": "1.2", "unit": 1, "stem": "Unlike a market economy, a command economy uses", "options": [{"key": "A", "text": "more centralized planning in economic decision making", "error": null}, {"key": "B", "text": "consumer sovereignty to make production decisions", "error": "C1"}, {"key": "C", "text": "its resources more efficiently", "error": "C1"}, {"key": "D", "text": "price signals in economic decision making", "error": "C1"}], "correct": "A", "explanation": "Decide whether the allocation is made by markets, prices, and private incentives or by government planning and public ownership.", "zh": "计划经济依赖集中规划；市场经济由价格以及买卖双方的互动配置资源。", "skill": "concept", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 8, "sourceSection": "1.2"}, {"id": "legacy-009", "topic": "1.2", "unit": 1, "stem": "For an economy consisting of households and businesses only, which of the following is consistent with the circular flow of income and production?", "options": [{"key": "A", "text": "Households are producers of goods and services and consumers of resources.", "error": "C1"}, {"key": "B", "text": "Households are users of resources, and businesses are sources of saving.", "error": "C1"}, {"key": "C", "text": "Households are suppliers of resources and consumers of goods and services.", "error": null}, {"key": "D", "text": "Businesses are users of taxes,and households are sources of taxes.", "error": "C1"}], "correct": "C", "explanation": "Households supply resources and demand goods; firms demand resources and supply goods and services.", "zh": "计划经济依赖集中规划；市场经济由价格以及买卖双方的互动配置资源。", "skill": "concept", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 9, "sourceSection": "1.2"}, {"id": "legacy-010", "topic": "1.2", "unit": 1, "stem": "Which of the following is associated with a command economy?", "options": [{"key": "A", "text": "Competitive product markets", "error": "C1"}, {"key": "B", "text": "Use of resources for private gain", "error": "C1"}, {"key": "C", "text": "Use of available resources to meet all the needs and wants of its citizens", "error": "C1"}, {"key": "D", "text": "Public ownership of the means of production", "error": null}], "correct": "D", "explanation": "Decide whether the allocation is made by markets, prices, and private incentives or by government planning and public ownership.", "zh": "计划经济依赖集中规划；市场经济由价格以及买卖双方的互动配置资源。", "skill": "concept", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 10, "sourceSection": "1.2"}, {"id": "legacy-011", "topic": "1.2", "unit": 1, "stem": "Assume there are two goods in a market economy. The amount of each good produced is determined by", "options": [{"key": "A", "text": "buyers and sellers’ interactions in the market for each good", "error": null}, {"key": "B", "text": "a central planning agency", "error": "C1"}, {"key": "C", "text": "the desires of households only", "error": "C1"}, {"key": "D", "text": "each citizen's minimum needs for survival", "error": "C1"}], "correct": "A", "explanation": "Decide whether the allocation is made by markets, prices, and private incentives or by government planning and public ownership.", "zh": "计划经济依赖集中规划；市场经济由价格以及买卖双方的互动配置资源。", "skill": "concept", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 11, "sourceSection": "1.2"}, {"id": "legacy-012", "topic": "1.2", "unit": 1, "stem": "In contrast to a market economy, a command economy relies on which of the following?", "options": [{"key": "A", "text": "The private sector in deciding what goods will be produced", "error": "C1"}, {"key": "B", "text": "Private ownership of resources", "error": "C1"}, {"key": "C", "text": "Profits as incentives to make choices", "error": "C1"}, {"key": "D", "text": "The government to allocate resources", "error": null}], "correct": "D", "explanation": "Decide whether the allocation is made by markets, prices, and private incentives or by government planning and public ownership.", "zh": "计划经济依赖集中规划；市场经济由价格以及买卖双方的互动配置资源。", "skill": "concept", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 12, "sourceSection": "1.2"}, {"id": "legacy-015", "topic": "1.3", "unit": 1, "stem": "A production possibilities curve that is concave to the origin(bowed out) implies that as more of a good is produced, the opportunity cost", "options": [{"key": "A", "text": "Remains constant", "error": "C1"}, {"key": "B", "text": "Decreases", "error": "C1"}, {"key": "C", "text": "Decrease first and then increases", "error": "C1"}, {"key": "D", "text": "Increases", "error": null}], "correct": "D", "explanation": "Use the PPC to identify scarcity, opportunity cost, efficiency, underutilization, unattainable points, and economic growth.", "zh": "先判断曲线形状与资源利用状态：增加产能移动 PPC，充分利用闲置资源只是靠近原曲线。", "skill": "concept", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 15, "sourceSection": "1.3"}, {"id": "legacy-016", "topic": "1.3", "unit": 1, "stem": "An economy produces two goods: X and Y. Its production possibilities curve is linear with the intercept on the Y axis at 1,000 units and the intercept on the X axis at 100 units. Which of the following statements is correct?", "options": [{"key": "A", "text": "There is an increasing opportunity cost of producing good X, beginning with 1 unit of X costing 0.1 unit of Y.", "error": "C1"}, {"key": "B", "text": "There is an increasing opportunity cost of producing good Y but not of producing good X, which has a constant opportunity cost.", "error": "C1"}, {"key": "C", "text": "There is a constant opportunity cost with each unit of good X costing 10 units of good Y.", "error": null}, {"key": "D", "text": "There is a constant opportunity cost with 10 units of good X costing 1 unit of good Y.", "error": "C1"}], "correct": "C", "explanation": "A straight PPC has constant opportunity cost. Giving up 1,000 Y allows 100 X, so one X costs 10 Y.", "zh": "先判断曲线形状与资源利用状态：增加产能移动 PPC，充分利用闲置资源只是靠近原曲线。", "skill": "concept", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 16, "sourceSection": "1.3"}, {"id": "legacy-017", "topic": "1.3", "unit": 1, "stem": "Assume an economy uses one input, labor, to produce two goods, X and Y, with constant opportunity cost. Which of the following would cause a outward shift of the production possibilities curve ?", "options": [{"key": "A", "text": "An increase in the productivity of labor with respect to producing good X", "error": "C1"}, {"key": "B", "text": "An increase in the amount of labor available for production", "error": null}, {"key": "C", "text": "A reduction in the unemployment of labor", "error": "C1"}, {"key": "D", "text": "An increase in the demand for good X and good Y", "error": "C1"}], "correct": "B", "explanation": "Use the PPC to identify scarcity, opportunity cost, efficiency, underutilization, unattainable points, and economic growth.", "zh": "先判断曲线形状与资源利用状态：增加产能移动 PPC，充分利用闲置资源只是靠近原曲线。", "skill": "concept", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 17, "sourceSection": "1.3"}, {"id": "legacy-018", "topic": "1.3", "unit": 1, "stem": "When an economy producing two goods is operating efficiently and at full employment, increasing the production of one good will result in", "options": [{"key": "A", "text": "an inward shift of the production possibilities curve", "error": "C1"}, {"key": "B", "text": "an outward shift of the production possibilities curve", "error": "C1"}, {"key": "C", "text": "a decrease in the amount of the other good that can be produced", "error": null}, {"key": "D", "text": "an increase in the costs of both goods", "error": "C1"}], "correct": "C", "explanation": "Use the PPC to identify scarcity, opportunity cost, efficiency, underutilization, unattainable points, and economic growth.", "zh": "先判断曲线形状与资源利用状态：增加产能移动 PPC，充分利用闲置资源只是靠近原曲线。", "skill": "concept", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 18, "sourceSection": "1.3"}, {"id": "legacy-020", "topic": "1.4", "unit": 1, "stem": "Cindy and Martin both sew t-shirts in a small factory. Using the same resources, Martin can sew twelve t-shirts and Cindy can sew nine t-shirts in one day. Which of the following can be concluded from the given information?", "options": [{"key": "A", "text": "Martin has a higher opportunity cost of sewing t-shirts than Cindy does.", "error": "C1"}, {"key": "B", "text": "Cindy has a comparative advantage in sewing t-shirts.", "error": "C1"}, {"key": "C", "text": "Martin has a comparative advantage in sewing t-shirts.", "error": "C1"}, {"key": "D", "text": "Martin has an absolute advantage in sewing t-shirts.", "error": null}], "correct": "D", "explanation": "Compare opportunity costs, not just absolute productivity; specialization follows comparative advantage and trade can increase consumption possibilities.", "zh": "比较优势取决于较低的机会成本；绝对优势只比较同等投入的产出。贸易可以使消费超出 PPC。", "skill": "concept", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 20, "sourceSection": "1.4"}, {"id": "legacy-021", "topic": "1.4", "unit": 1, "stem": "Assume both Italy and Greece produce only two goods: wine and olive oil. If Italy holds a comparative advantage in the production of wine, then which of the following statements is NOT true?", "options": [{"key": "A", "text": "Italy must hold an absolute advantage in the production of wine.", "error": null}, {"key": "B", "text": "Greece holds a comparative advantage in the production of olive oil.", "error": "C1"}, {"key": "C", "text": "Italy’s opportunity cost of producing one additional unit of wine is lower than Greece’s.", "error": "C1"}, {"key": "D", "text": "Greece’s opportunity cost of producing one additional unit of olive oil is lower than Italy’s.", "error": "C1"}], "correct": "A", "explanation": "Compare opportunity costs, not just absolute productivity; specialization follows comparative advantage and trade can increase consumption possibilities.", "zh": "比较优势取决于较低的机会成本；绝对优势只比较同等投入的产出。贸易可以使消费超出 PPC。", "skill": "concept", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 21, "sourceSection": "1.4"}, {"id": "legacy-024", "topic": "1.4", "unit": 1, "stem": "Which of the following statements regarding specialization and trade is true?", "options": [{"key": "A", "text": "With specialization and trade, a country’s production possibilities curve shifts out, showing an increase in productive capacity.", "error": "C1"}, {"key": "B", "text": "With specialization and trade, a country will produce a combination of goods beyond its production possibilities curve.", "error": "C1"}, {"key": "C", "text": "To gain from trade, countries specialize in producing goods and services in which they have an absolute advantage.", "error": "C1"}, {"key": "D", "text": "With specialization and trade, a country can consume beyond its production possibilities curve.", "error": null}], "correct": "D", "explanation": "Compare opportunity costs, not just absolute productivity; specialization follows comparative advantage and trade can increase consumption possibilities.", "zh": "比较优势取决于较低的机会成本；绝对优势只比较同等投入的产出。贸易可以使消费超出 PPC。", "skill": "concept", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 24, "sourceSection": "1.4"}, {"id": "legacy-025", "topic": "1.4", "unit": 1, "stem": "Assume a worker can either cut grass or wash windows in a given day. It takes 5 hours to mow a one-acre lawn and 2.5 hours to wash all the windows in a house. When a worker chooses to wash the windows of four houses in a neighborhood, what is the opportunity cost of this decision?", "options": [{"key": "A", "text": "The pay the worker receives for washing the windows in the four houses", "error": "C1"}, {"key": "B", "text": "The pay the worker would receive for cutting one lawn", "error": "C1"}, {"key": "C", "text": "Cutting the grass at the same four houses", "error": "C1"}, {"key": "D", "text": "The pay the worker would have received from cutting the grass at two houses", "error": null}], "correct": "D", "explanation": "Four window-washing jobs take 4 × 2.5 = 10 hours. In that time the worker could mow 10 / 5 = 2 lawns.", "zh": "比较优势取决于较低的机会成本；绝对优势只比较同等投入的产出。贸易可以使消费超出 PPC。", "skill": "concept", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 25, "sourceSection": "1.4"}, {"id": "legacy-026", "topic": "1.4", "unit": 1, "stem": "In the country Beta it takes two hours of labor to produce a unit of tea and four hours of labor to produce a unit of bread. In the country Zeta it takes three hours of labor to produce a unit of tea and nine hours of labor to produce a unit of bread. Which of the following is true?", "options": [{"key": "A", "text": "Country Zeta has an absolute advantage in producing both tea and bread.", "error": "C1"}, {"key": "B", "text": "Country Zeta has an absolute advantage and a comparative advantage in producing tea.", "error": "C1"}, {"key": "C", "text": "Country Beta has an absolute advantage and a comparative advantage in producing tea.", "error": "C1"}, {"key": "D", "text": "Country Beta has the lower opportunity cost in producing bread and therefore a comparative advantage in producing bread.", "error": null}], "correct": "D", "explanation": "One bread costs Beta 4/2 = 2 tea and Zeta 9/3 = 3 tea. Beta therefore has comparative advantage in bread.", "zh": "比较优势取决于较低的机会成本；绝对优势只比较同等投入的产出。贸易可以使消费超出 PPC。", "skill": "concept", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 26, "sourceSection": "1.4"}, {"id": "legacy-027", "topic": "1.5", "unit": 1, "stem": "Karen works part-time at a local convenience store and earns $10 per hour. She wants to spend next Saturday afternoon attending a music concert. The full price of a concert ticket is $75, but Karen was able to get a discounted price of $50 from a friend who purchased the ticket but has become unable to attend.If Karen took 4 hours off from her job to attend the concert, what was her opportunity cost of attending the concert? Assume the ticket cannot be resold and all other expenses are unchanged.", "options": [{"key": "A", "text": "$40", "error": "C1"}, {"key": "B", "text": "$50", "error": "C1"}, {"key": "C", "text": "$75", "error": "C1"}, {"key": "D", "text": "$90", "error": null}], "correct": "D", "explanation": "calculation of opportunity cost = explicit cost + implicit cost.", "zh": "经济成本包括显性支出与隐性机会成本；选择总净收益更高的方案。", "skill": "concept", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 27, "sourceSection": "1.5"}, {"id": "legacy-028", "topic": "1.5", "unit": 1, "stem": "Using cost-benefit analysis, a local government would decide to build a new bridge if", "options": [{"key": "A", "text": "The additional tax paid by an individual resident is greater than the additional benefit of building the bridge for all residents.", "error": "C1"}, {"key": "B", "text": "The toll paid by an individual resident crossing the bridge is less than the resident’s benefit from crossing the bridge.", "error": "C1"}, {"key": "C", "text": "The total costs of building the bridge are less than the total benefits from building the bridge.", "error": null}, {"key": "D", "text": "The total costs of building the bridge are greater than the total benefits from building the bridge.", "error": "C1"}], "correct": "C", "explanation": "Choose an action when total or marginal benefits exceed the relevant total or marginal costs, including opportunity costs.", "zh": "经济成本包括显性支出与隐性机会成本；选择总净收益更高的方案。", "skill": "concept", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 28, "sourceSection": "1.5"}, {"id": "legacy-029", "topic": "1.6", "unit": 1, "stem": "Suppose that a consumer purchases two goods X and Y and that the marginal utility of X is MUx, the total utility of X is TUx, the marginal utility of Y is MUy, and the total utility of Y is TUy. If the prices of X and Y are Px and Py, respectively, which of the following expressions defines consumer equilibrium?", "options": [{"key": "A", "text": "TUx=TUy", "error": "C1"}, {"key": "B", "text": "MUx = MUy", "error": "C1"}, {"key": "C", "text": "TUx/Px=TUy/Py", "error": "C1"}, {"key": "D", "text": "MUx/Px=MUy/Py", "error": null}], "correct": "D", "explanation": "Compare marginal benefit with marginal cost or marginal utility per dollar; optimal choices equalize marginal utility per dollar across goods.", "zh": "比较 MU/P，将支出转向每元边际效用更高的商品，而不是简单比较总效用。", "skill": "concept", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 29, "sourceSection": "1.6"}, {"id": "legacy-030", "topic": "1.6", "unit": 1, "stem": "Assume a consumer is spending all her income on two goods: X and Y. At the current consumption combination of the two goods, if the marginal utility per dollar spent on the last unit of good X exceeds that of the marginal utility per dollar spent on the last unit of good Y, what should the consumer do to maximize utility?", "options": [{"key": "A", "text": "Purchase more units of X and more units of Y.", "error": "C1"}, {"key": "B", "text": "Decrease the price of good X.", "error": "C1"}, {"key": "C", "text": "Purchase more units of X and less units of Y.", "error": null}, {"key": "D", "text": "Increase income to buy more of both good Y and good X.", "error": "C1"}], "correct": "C", "explanation": "Compare marginal benefit with marginal cost or marginal utility per dollar; optimal choices equalize marginal utility per dollar across goods.", "zh": "比较 MU/P，将支出转向每元边际效用更高的商品，而不是简单比较总效用。", "skill": "concept", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 30, "sourceSection": "1.6"}, {"id": "legacy-031", "topic": "1.6", "unit": 1, "stem": "Assume the price of a candy bar is $2 and the price of a bag of chips is $3. Assume Lilly’s marginal utility from consuming an additional candy bar is 10 utils and her marginal utility from consuming an additional bag of chips is 12 utils. If Lilly is spending her fixed weekly allowance on candy bars and bags of chips, which of the following actions will maximize Lilly’s total utility?", "options": [{"key": "A", "text": "Buying more candy bars and bags of chips", "error": "C1"}, {"key": "B", "text": "Buying more candy bars and fewer bags of chips", "error": null}, {"key": "C", "text": "Buying fewer candy bars and more bags of chips", "error": "C1"}, {"key": "D", "text": "Buying fewer candy bars and bags of chips", "error": "C1"}], "correct": "B", "explanation": "Candy gives 10/2 = 5 utils per dollar; chips give 12/3 = 4. Move spending toward candy.", "zh": "比较 MU/P，将支出转向每元边际效用更高的商品，而不是简单比较总效用。", "skill": "concept", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 31, "sourceSection": "1.6"}, {"id": "legacy-034", "topic": "2.1", "unit": 2, "stem": "If demand for mp3 players increases when the price of mobile phones increases, we can say that cell phones and mp3 players are", "options": [{"key": "A", "text": "Normal goods", "error": "V2"}, {"key": "B", "text": "Inferior goods", "error": "V2"}, {"key": "C", "text": "Substitute goods", "error": null}, {"key": "D", "text": "Complementary goods", "error": "V2"}], "correct": "C", "explanation": "Distinguish a change in quantity demanded from a demand shift caused by income, tastes, related goods, expectations, or number of buyers.", "zh": "本商品价格改变导致沿需求曲线移动；收入、偏好及相关商品价格改变会移动需求曲线。", "skill": "concept", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 34, "sourceSection": "2.1"}, {"id": "legacy-035", "topic": "2.1", "unit": 2, "stem": "Which of the following will cause the demand for milk to decrease?", "options": [{"key": "A", "text": "Increase in the price of a substitute", "error": "V2"}, {"key": "B", "text": "Decrease in income assuming that milk is a normal good", "error": null}, {"key": "C", "text": "Decrease in the price of milk", "error": "V2"}, {"key": "D", "text": "Increase in the price of milk", "error": "V2"}], "correct": "B", "explanation": "Distinguish a change in quantity demanded from a demand shift caused by income, tastes, related goods, expectations, or number of buyers.", "zh": "本商品价格改变导致沿需求曲线移动；收入、偏好及相关商品价格改变会移动需求曲线。", "skill": "concept", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 35, "sourceSection": "2.1"}, {"id": "legacy-036", "topic": "2.1", "unit": 2, "stem": "Which of the following will cause the quantity demanded of milk to decrease?", "options": [{"key": "A", "text": "Increase in the price of a substitute", "error": "V2"}, {"key": "B", "text": "Decrease in income assuming that milk is a normal good", "error": "V2"}, {"key": "C", "text": "Decrease in the price of milk", "error": "V2"}, {"key": "D", "text": "An increase in the price of milk", "error": null}], "correct": "D", "explanation": "Distinguish a change in quantity demanded from a demand shift caused by income, tastes, related goods, expectations, or number of buyers.", "zh": "本商品价格改变导致沿需求曲线移动；收入、偏好及相关商品价格改变会移动需求曲线。", "skill": "concept", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 36, "sourceSection": "2.1"}, {"id": "legacy-037", "topic": "2.1", "unit": 2, "stem": "Which of the following will cause the demand for a normal good to increase?", "options": [{"key": "A", "text": "A decrease in consumers’ income", "error": "V2"}, {"key": "B", "text": "A decrease in the price of a complementary good", "error": null}, {"key": "C", "text": "A decrease in the price of a substitute good", "error": "V2"}, {"key": "D", "text": "A decrease in the price of the good", "error": "V2"}], "correct": "B", "explanation": "Distinguish a change in quantity demanded from a demand shift caused by income, tastes, related goods, expectations, or number of buyers.", "zh": "本商品价格改变导致沿需求曲线移动；收入、偏好及相关商品价格改变会移动需求曲线。", "skill": "concept", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 37, "sourceSection": "2.1"}, {"id": "legacy-038", "topic": "2.1", "unit": 2, "stem": "Which of the following best describes the law of demand?", "options": [{"key": "A", "text": "When income increases, the demand for goods increases.", "error": "V2"}, {"key": "B", "text": "When the price of a good decreases, the demand for the good increases.", "error": "V2"}, {"key": "C", "text": "When the price of a good decreases, the quantity demanded of the good decreases.", "error": "V2"}, {"key": "D", "text": "When the price of a good increases, the quantity demanded of the good decreases.", "error": null}], "correct": "D", "explanation": "Distinguish a change in quantity demanded from a demand shift caused by income, tastes, related goods, expectations, or number of buyers.", "zh": "本商品价格改变导致沿需求曲线移动；收入、偏好及相关商品价格改变会移动需求曲线。", "skill": "concept", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 38, "sourceSection": "2.1"}, {"id": "legacy-039", "topic": "2.2", "unit": 2, "stem": "Which of the following will cause the quantity supplied of milk to decrease?", "options": [{"key": "A", "text": "Decrease in the price of a key resource", "error": "V2"}, {"key": "B", "text": "Decrease in the number of milk producers", "error": "V2"}, {"key": "C", "text": "Decrease in the price of milk", "error": null}, {"key": "D", "text": "An increase in the price of milk", "error": "V2"}], "correct": "C", "explanation": "Distinguish a change in quantity supplied from a supply shift caused by input prices, technology, taxes/subsidies, expectations, or number of sellers.", "zh": "本商品价格改变导致沿供给曲线移动；投入成本改变会移动供给曲线。", "skill": "concept", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 39, "sourceSection": "2.2"}, {"id": "legacy-040", "topic": "2.2", "unit": 2, "stem": "The supply curve for automobiles will shift to the left in response to", "options": [{"key": "A", "text": "an increase in the efficiency of robot technology", "error": "V2"}, {"key": "B", "text": "an increase in wages in the automobile industry", "error": null}, {"key": "C", "text": "a decrease in the number of consumers purchasing automobiles", "error": "V2"}, {"key": "D", "text": "a decrease in the interest rates for automobile loans", "error": "V2"}], "correct": "B", "explanation": "Distinguish a change in quantity supplied from a supply shift caused by input prices, technology, taxes/subsidies, expectations, or number of sellers.", "zh": "本商品价格改变导致沿供给曲线移动；投入成本改变会移动供给曲线。", "skill": "concept", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 40, "sourceSection": "2.2"}, {"id": "legacy-041", "topic": "2.2", "unit": 2, "stem": "Which of the following changes will lead to an increase in the supply of good X?", "options": [{"key": "A", "text": "An increase in the price of good X", "error": "V2"}, {"key": "B", "text": "An increase in the wages of labor used to produce good X", "error": "V2"}, {"key": "C", "text": "A decrease in the price of energy, a key input to the production of good X", "error": null}, {"key": "D", "text": "An increase in the demand for good X", "error": "V2"}], "correct": "C", "explanation": "Distinguish a change in quantity supplied from a supply shift caused by input prices, technology, taxes/subsidies, expectations, or number of sellers.", "zh": "本商品价格改变导致沿供给曲线移动；投入成本改变会移动供给曲线。", "skill": "concept", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 41, "sourceSection": "2.2"}, {"id": "legacy-042", "topic": "2.2", "unit": 2, "stem": "Which of the following statements relating to supply is true?", "options": [{"key": "A", "text": "An increase in an input price will lead to an increase in supply.", "error": "V2"}, {"key": "B", "text": "An increase in the price of a good will lead to an increase in the supply of the good.", "error": "V2"}, {"key": "C", "text": "A decrease in consumers’ income will lead to a decrease in the supply of the good.", "error": "V2"}, {"key": "D", "text": "A decrease in the price of a good will lead to a decrease in the quantity supplied of the good.", "error": null}], "correct": "D", "explanation": "Distinguish a change in quantity supplied from a supply shift caused by input prices, technology, taxes/subsidies, expectations, or number of sellers.", "zh": "本商品价格改变导致沿供给曲线移动；投入成本改变会移动供给曲线。", "skill": "concept", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 42, "sourceSection": "2.2"}, {"id": "legacy-043", "topic": "2.2", "unit": 2, "stem": "Which of the following statements about the market supply curve is true?", "options": [{"key": "A", "text": "An increase in input prices will shift the market supply curve to the right.", "error": "V2"}, {"key": "B", "text": "At each price, a horizontal summation of the quantity supplied by each firm will yield the market supply curve.", "error": null}, {"key": "C", "text": "At each quantity supplied, a vertical summation of the price set by each firm will yield the market supply curve.", "error": "V2"}, {"key": "D", "text": "A decrease in the price will shift the market supply curve to the left.", "error": "V2"}], "correct": "B", "explanation": "Distinguish a change in quantity supplied from a supply shift caused by input prices, technology, taxes/subsidies, expectations, or number of sellers.", "zh": "本商品价格改变导致沿供给曲线移动；投入成本改变会移动供给曲线。", "skill": "concept", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 43, "sourceSection": "2.2"}, {"id": "legacy-045", "topic": "2.7", "unit": 2, "stem": "A simultaneous increase in both the demand for and the supply of a good in a market will lead to which of the following changes in the equilibrium price and quantity of the good? Price Quantity", "options": [{"key": "A", "text": "Increase increase", "error": "C1"}, {"key": "B", "text": "Indeterminate decrease", "error": "C1"}, {"key": "C", "text": "Indeterminate increase", "error": null}, {"key": "D", "text": "Increase indeterminate", "error": "C1"}], "correct": "C", "explanation": "Track demand and supply shifts to determine equilibrium price and quantity; draw a graph.", "zh": "分别判断供需变化：两者均增加时，数量增加而价格取决于相对移动幅度。", "skill": "concept", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 45, "sourceSection": "2.3"}, {"id": "legacy-046", "topic": "2.7", "unit": 2, "stem": "Assume that consumers consider popcorn and pretzels to be substitutes. A significant decrease in the supply of popcorn will affect the pretzel market by", "options": [{"key": "A", "text": "increasing the demand for pretzels and therefore the supply of pretzels", "error": "C1"}, {"key": "B", "text": "increasing the demand for pretzels and therefore the price of pretzels", "error": null}, {"key": "C", "text": "decreasing the demand for pretzels and therefore the price of pretzels", "error": "C1"}, {"key": "D", "text": "increasing the supply of pretzels and therefore the price of pretzels", "error": "C1"}], "correct": "B", "explanation": "Track demand and supply shifts to determine equilibrium price and quantity; draw a graph.", "zh": "分别判断供需变化：两者均增加时，数量增加而价格取决于相对移动幅度。", "skill": "concept", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 46, "sourceSection": "2.3"}, {"id": "legacy-047", "topic": "2.7", "unit": 2, "stem": "Which of the following would most likely result in a decrease in the equilibrium price of oranges?", "options": [{"key": "A", "text": "The weather during this orange-growing season is not as good as it was last year.", "error": "C1"}, {"key": "B", "text": "The price of apples, a substitute for oranges, is higher this year than last year.", "error": "C1"}, {"key": "C", "text": "New studies suggest that oranges contain traces of cancer-causing substances due to pesticide residue.", "error": null}, {"key": "D", "text": "A tree-killing fungus spreads through orange orchards across the country.", "error": "C1"}], "correct": "C", "explanation": "Track demand and supply shifts to determine equilibrium price and quantity; draw a graph.", "zh": "分别判断供需变化：两者均增加时，数量增加而价格取决于相对移动幅度。", "skill": "concept", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 47, "sourceSection": "2.3"}, {"id": "legacy-048", "topic": "2.8", "unit": 2, "stem": "Assume the government imposes a price floor above the current equilibrium price in the market for a good. Which of the following will occur?", "options": [{"key": "A", "text": "Since the price floor is set above the equilibrium price, nothing will change because the price floor is not binding.", "error": "P1"}, {"key": "B", "text": "There will be a shortage of the good.", "error": "P1"}, {"key": "C", "text": "Compared to the equilibrium price, there will be an increase in the quantity exchanged.", "error": "P1"}, {"key": "D", "text": "There will be an excess supply of the good.", "error": null}], "correct": "D", "explanation": "A binding price ceiling is below equilibrium and causes a shortage; a binding price floor is above equilibrium and causes a surplus.", "zh": "有效价格管制才会改变均衡。税收收入等于单位税乘以税后数量；税负取决于相对弹性。", "skill": "policy", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 48, "sourceSection": "2.3"}, {"id": "legacy-049", "topic": "2.3", "unit": 2, "stem": "A company decided to reduce the price of its product by 10%.What would happen?", "options": [{"key": "A", "text": "The firm’s costs would decrease if the elasticity of demand was greater than one.", "error": "M1"}, {"key": "B", "text": "The firm’s profits would decrease if the elasticity of demand was greater than one.", "error": "M1"}, {"key": "C", "text": "The firm’s revenue would increase if the elasticity of demand was greater than one.", "error": null}, {"key": "D", "text": "The quantity sold would decrease if the elasticity of demand was less than one.", "error": "M1"}], "correct": "C", "explanation": "relationship between PED and TR", "zh": "需求价格弹性取数量变化百分比除以价格变化百分比的绝对值。富有弹性时降价会增加总收益。", "skill": "calculation", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 49, "sourceSection": "2.5"}, {"id": "legacy-050", "topic": "2.3", "unit": 2, "stem": "A product has a price elasticity of demand that is greater than one. What will happen to total revenue if the price of the product is reduced by 3%?", "options": [{"key": "A", "text": "It will fall by more than 3%.", "error": "M1"}, {"key": "B", "text": "It will fall to zero.", "error": "M1"}, {"key": "C", "text": "It will be unchanged.", "error": "M1"}, {"key": "D", "text": "It will rise.", "error": null}], "correct": "D", "explanation": "relationship between PED and TR", "zh": "需求价格弹性取数量变化百分比除以价格变化百分比的绝对值。富有弹性时降价会增加总收益。", "skill": "calculation", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 50, "sourceSection": "2.5"}, {"id": "legacy-051", "topic": "2.3", "unit": 2, "stem": "Moving from left to right along a downward-sloping linear demand curve, price elasticity varies in which of the following ways?", "options": [{"key": "A", "text": "First unit elastic,then inelastic throughout", "error": "M1"}, {"key": "B", "text": "First unit elastic,then elastic throughout", "error": "M1"}, {"key": "C", "text": "First inelastic,then unit elastic throughout", "error": "M1"}, {"key": "D", "text": "First elastic,then unit elastic,and finally inelastic", "error": null}], "correct": "D", "explanation": "change of PED along D curve", "zh": "需求价格弹性取数量变化百分比除以价格变化百分比的绝对值。富有弹性时降价会增加总收益。", "skill": "calculation", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 51, "sourceSection": "2.5"}, {"id": "legacy-052", "topic": "2.3", "unit": 2, "stem": "Promoters of a rock group know that if they charged $8 a ticket, 400 people would buy tickets for a concert, and if they charged $4 a ticket, 800 people would buy tickets. Over this price range, the demand for the concert tickets for the rock group is Use the midpoint method.", "options": [{"key": "A", "text": "elastic", "error": "M1"}, {"key": "B", "text": "inelastic", "error": "M1"}, {"key": "C", "text": "unit elastic", "error": null}, {"key": "D", "text": "perfectly elastic", "error": "M1"}], "correct": "C", "explanation": "Revenue is $8 × 400 = $3,200 and $4 × 800 = $3,200. Midpoint percentage changes are equal in magnitude, so arc demand is unit elastic.", "zh": "需求价格弹性取数量变化百分比除以价格变化百分比的绝对值。富有弹性时降价会增加总收益。", "skill": "calculation", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 52, "sourceSection": "2.5"}, {"id": "legacy-053", "topic": "2.3", "unit": 2, "stem": "Which of the following statements about the price elasticity of demand is true?", "options": [{"key": "A", "text": "When demand is price inelastic, total revenue will decrease as price increases.", "error": "M1"}, {"key": "B", "text": "When demand is price elastic, an increase in price will increase total revenue.", "error": "M1"}, {"key": "C", "text": "Demand tends to be more elastic in the short run compared to the long run.", "error": "M1"}, {"key": "D", "text": "As more close substitutes become available, demand tends to be more price elastic.", "error": null}], "correct": "D", "explanation": "factors influencing PED", "zh": "需求价格弹性取数量变化百分比除以价格变化百分比的绝对值。富有弹性时降价会增加总收益。", "skill": "calculation", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 53, "sourceSection": "2.5"}, {"id": "legacy-054", "topic": "2.3", "unit": 2, "stem": "Assume that the price of orange juice increases by 40 percent following a crop failure. If the quantity demanded falls by 10 percent, which of the following is true?", "options": [{"key": "A", "text": "The demand for orange juice is elastic.", "error": "M1"}, {"key": "B", "text": "The price of grapefruit juice, a substitute good, will fall.", "error": "M1"}, {"key": "C", "text": "The absolute value of the price elasticity of demand for orange juice is 4.", "error": "M1"}, {"key": "D", "text": "The absolute value of the price elasticity of demand for orange juice is 0.25.", "error": null}], "correct": "D", "explanation": "Absolute demand elasticity = 10% / 40% = 0.25.", "zh": "需求价格弹性取数量变化百分比除以价格变化百分比的绝对值。富有弹性时降价会增加总收益。", "skill": "calculation", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 54, "sourceSection": "2.5"}, {"id": "legacy-055", "topic": "2.3", "unit": 2, "stem": "The price elasticity of demand for a product is 0.5. If the price of the product increases by 20 percent, which of the following will occur?", "options": [{"key": "A", "text": "The quantity demanded of the good will increase by 10%.", "error": "M1"}, {"key": "B", "text": "The quantity demanded of the good will increase by 20%.", "error": "M1"}, {"key": "C", "text": "The quantity demanded of the good will increase by 40%.", "error": "M1"}, {"key": "D", "text": "The quantity demanded of the good will decrease by 10%.", "error": null}], "correct": "D", "explanation": "Quantity demanded changes by −0.5 × 20% = −10%.", "zh": "需求价格弹性取数量变化百分比除以价格变化百分比的绝对值。富有弹性时降价会增加总收益。", "skill": "calculation", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 55, "sourceSection": "2.5"}, {"id": "legacy-056", "topic": "2.4", "unit": 2, "stem": "Which of the following must be true for original Michelangelo sculptures?", "options": [{"key": "A", "text": "The demand is relatively elastic", "error": "M1"}, {"key": "B", "text": "The supply is perfectly elastic", "error": "M1"}, {"key": "C", "text": "The demand is perfectly inelastic", "error": "M1"}, {"key": "D", "text": "The supply is perfectly inelastic", "error": null}], "correct": "D", "explanation": "definition of PES", "zh": "供给价格弹性等于供给量变化百分比除以价格变化百分比；大于 1 为富有弹性。", "skill": "calculation", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 56, "sourceSection": "2.6"}, {"id": "legacy-057", "topic": "2.4", "unit": 2, "stem": "The quantity of peanuts supplied increased from 40 tons per week to 60 tons per week when the price of peanuts increased from $4 per ton to $5 per ton. The price elasticity of supply for peanuts over this price range is", "options": [{"key": "A", "text": "elastic", "error": null}, {"key": "B", "text": "inelastic", "error": "M1"}, {"key": "C", "text": "unit elastic", "error": "M1"}, {"key": "D", "text": "perfectly elastic", "error": "M1"}], "correct": "A", "explanation": "Use Es = percent change in quantity supplied divided by percent change in price; compare the percentage responses to classify supply.", "zh": "供给价格弹性等于供给量变化百分比除以价格变化百分比；大于 1 为富有弹性。", "skill": "calculation", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 57, "sourceSection": "2.6"}, {"id": "legacy-058", "topic": "2.4", "unit": 2, "stem": "If the value of the price elasticity of supply is 3, which of the following is true?", "options": [{"key": "A", "text": "Supply is inelastic.", "error": "M1"}, {"key": "B", "text": "A percentage increase in price will lead to a relatively smaller percentage increase in quantity supplied.", "error": "M1"}, {"key": "C", "text": "The supply curve is downward sloping with respect to the price of output.", "error": "M1"}, {"key": "D", "text": "A 10 percent decrease in price will decrease the quantity supplied by 30 percent.", "error": null}], "correct": "D", "explanation": "Use Es = percent change in quantity supplied divided by percent change in price.", "zh": "供给价格弹性等于供给量变化百分比除以价格变化百分比；大于 1 为富有弹性。", "skill": "calculation", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 58, "sourceSection": "2.6"}, {"id": "legacy-059", "topic": "2.4", "unit": 2, "stem": "Assume that the price elasticity of supply for good Y is 0.5. If the price of good Y decreases by 30 percent, the quantity supplied of good Y will", "options": [{"key": "A", "text": "decrease by 60 percent", "error": "M1"}, {"key": "B", "text": "decrease by 30 percent", "error": "M1"}, {"key": "C", "text": "decrease by 15 percent", "error": null}, {"key": "D", "text": "increase by 0.5 percent", "error": "M1"}], "correct": "C", "explanation": "Quantity supplied changes by 0.5 × (−30%) = −15%.", "zh": "供给价格弹性等于供给量变化百分比除以价格变化百分比；大于 1 为富有弹性。", "skill": "calculation", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 59, "sourceSection": "2.6"}, {"id": "legacy-060", "topic": "2.4", "unit": 2, "stem": "Assume a 10 percent increase in price increased the market quantity supplied by 20 percent. Which of the following is true?", "options": [{"key": "A", "text": "The value of the price elasticity of supply is 2.", "error": null}, {"key": "B", "text": "The value of the price elasticity of supply is 0.5.", "error": "M1"}, {"key": "C", "text": "Supply is price inelastic.", "error": "M1"}, {"key": "D", "text": "Demand is price elastic.", "error": "M1"}], "correct": "A", "explanation": "Use Es = percent change in quantity supplied divided by percent change in price", "zh": "供给价格弹性等于供给量变化百分比除以价格变化百分比；大于 1 为富有弹性。", "skill": "calculation", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 60, "sourceSection": "2.6"}, {"id": "legacy-061", "topic": "2.5", "unit": 2, "stem": "If the income elasticity of demand for good X is negative and the cross-price elasticity of demand between good X and good Y is negative, which of the following must be true of good X?", "options": [{"key": "A", "text": "X is a normal good and is a substitute for Y.", "error": "M1"}, {"key": "B", "text": "X is a normal good and is a complement to Y.", "error": "M1"}, {"key": "C", "text": "X is an inferior good and is a substitute for Y.", "error": "M1"}, {"key": "D", "text": "X is an inferior good and is a complement to Y.", "error": null}], "correct": "D", "explanation": "Use income elasticity to classify normal versus inferior goods and cross-price elasticity to classify substitutes versus complements.", "zh": "收入弹性正为正常品、负为劣等品；交叉价格弹性正为替代品、负为互补品。", "skill": "calculation", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 61, "sourceSection": "2.7"}, {"id": "legacy-062", "topic": "2.5", "unit": 2, "stem": "Following a decrease in the supply of oranges, the price of orange juice increased by 20 percent, which resulted in a 10 percent increase in the quantity of apple juice consumed.This implies that the cross elasticity of demand between orange juice and apple juice is", "options": [{"key": "A", "text": "0.5", "error": null}, {"key": "B", "text": "1", "error": "M1"}, {"key": "C", "text": "2", "error": "M1"}, {"key": "D", "text": "indeterminate", "error": "M1"}], "correct": "A", "explanation": "Cross-price elasticity = 10% / 20% = +0.5.", "zh": "收入弹性正为正常品、负为劣等品；交叉价格弹性正为替代品、负为互补品。", "skill": "calculation", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 62, "sourceSection": "2.7"}, {"id": "legacy-063", "topic": "2.5", "unit": 2, "stem": "If the cross price elasticity coefficient of goods A and B is -5 and the income elasticity of good A is 2, which of the following is true?", "options": [{"key": "A", "text": "A decrease in the price of good A will decrease the demand for good B", "error": "M1"}, {"key": "B", "text": "An increase in income will decrease the demand for good A", "error": "M1"}, {"key": "C", "text": "Goods A and B are substitutes", "error": "M1"}, {"key": "D", "text": "An increase in the price of A will decrease the demand for good B", "error": null}], "correct": "D", "explanation": "Use income elasticity to classify normal versus inferior goods and cross-price elasticity to classify substitutes versus complements.", "zh": "收入弹性正为正常品、负为劣等品；交叉价格弹性正为替代品、负为互补品。", "skill": "calculation", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 63, "sourceSection": "2.7"}, {"id": "legacy-064", "topic": "2.5", "unit": 2, "stem": "The cross-price elasticity of demand between goods J and K is -3. A 20 percent decrease in the price of good K will result in a", "options": [{"key": "A", "text": "3 percent decrease in the quantity demanded of good K", "error": "M1"}, {"key": "B", "text": "15 percent decrease in the quantity demanded of good K", "error": "M1"}, {"key": "C", "text": "6 percent increase in the quantity demanded of good J", "error": "M1"}, {"key": "D", "text": "60 percent increase in the quantity demanded of good J", "error": null}], "correct": "D", "explanation": "Quantity demanded of J changes by (−3) × (−20%) = +60%.", "zh": "收入弹性正为正常品、负为劣等品；交叉价格弹性正为替代品、负为互补品。", "skill": "calculation", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 64, "sourceSection": "2.7"}, {"id": "legacy-065", "topic": "2.5", "unit": 2, "stem": "Assume the income elasticity of demand for good Z equals -5.0. Which of the following is true?", "options": [{"key": "A", "text": "Good Z is a normal good.", "error": "M1"}, {"key": "B", "text": "Good Z must have an inelastic demand.", "error": "M1"}, {"key": "C", "text": "An increase in income will lead to a decrease in demand.", "error": null}, {"key": "D", "text": "An increase in income will lead to an increase in demand.", "error": "M1"}], "correct": "C", "explanation": "Use income elasticity to classify normal versus inferior goods", "zh": "收入弹性正为正常品、负为劣等品；交叉价格弹性正为替代品、负为互补品。", "skill": "calculation", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 65, "sourceSection": "2.7"}, {"id": "legacy-066", "topic": "2.5", "unit": 2, "stem": "Which of the following statements relating to income elasticity is true?", "options": [{"key": "A", "text": "A positive value for the income elasticity coefficient indicates an inferior good.", "error": "M1"}, {"key": "B", "text": "If good X and good Y have negative income elasticities, then both goods are substitutes.", "error": "M1"}, {"key": "C", "text": "With an income elasticity coefficient of 0.6, the demand is inelastic and the good is an inferior good.", "error": "M1"}, {"key": "D", "text": "With an income elasticity coefficient of 5, a 10 percent increase in income will lead to a 50 percent increase in the quantity demanded of the good.", "error": null}], "correct": "D", "explanation": "income elasticity", "zh": "收入弹性正为正常品、负为劣等品；交叉价格弹性正为替代品、负为互补品。", "skill": "calculation", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 66, "sourceSection": "2.7"}, {"id": "legacy-067", "topic": "2.8", "unit": 2, "stem": "Which of the following will occur if a legal price floor is placed on a good below its free market equilibrium?", "options": [{"key": "A", "text": "Surpluses will develop", "error": "P1"}, {"key": "B", "text": "Shortages will develop", "error": "P1"}, {"key": "C", "text": "Underground markets will develop", "error": "P1"}, {"key": "D", "text": "The equilibrium price and quantity will remain the same", "error": null}], "correct": "D", "explanation": "A binding price ceiling is below equilibrium and causes a shortage; a binding price floor is above equilibrium and causes a surplus.", "zh": "有效价格管制才会改变均衡。税收收入等于单位税乘以税后数量；税负取决于相对弹性。", "skill": "policy", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 67, "sourceSection": "2.8"}, {"id": "legacy-068", "topic": "2.8", "unit": 2, "stem": "Assume an initially efficient competitive market. Which statement about binding price controls is correct?", "options": [{"key": "A", "text": "A price ceiling causes a shortage if the ceiling price is above the equilibrium price", "error": "P1"}, {"key": "B", "text": "A price floor causes a surplus if the price floor is below the equilibrium price", "error": "P1"}, {"key": "C", "text": "Binding price ceilings and binding price floors result in a misallocation of resources.", "error": null}, {"key": "D", "text": "Price floors above equilibrium cause a shortage", "error": "P1"}], "correct": "C", "explanation": "A binding price ceiling is below equilibrium and causes a shortage; a binding price floor is above equilibrium and causes a surplus.", "zh": "有效价格管制才会改变均衡。税收收入等于单位税乘以税后数量；税负取决于相对弹性。", "skill": "policy", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 68, "sourceSection": "2.8"}, {"id": "legacy-074", "topic": "2.6", "unit": 2, "stem": "Assume that the market demand for a good is perfectly inelastic, the market supply for the good is perfectly elastic, and the market is in equilibrium. If there is a decrease in the price of a key input used in the production of the good, which of the following will occur?", "options": [{"key": "A", "text": "There will be a decrease in the equilibrium quantity.", "error": "C1"}, {"key": "B", "text": "There will be no change in the producer surplus.", "error": null}, {"key": "C", "text": "There will be a decrease in the producer surplus.", "error": "C1"}, {"key": "D", "text": "There will be a decrease in the consumer surplus.", "error": "C1"}], "correct": "B", "explanation": "Perfectly elastic supply is horizontal, so producer surplus is zero before and after the cost decrease. Quantity is fixed by perfectly inelastic demand.", "zh": "消费者剩余在需求曲线下价格线上，生产者剩余在价格线下供给曲线上。", "skill": "concept", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 74, "sourceSection": "2.8"}, {"id": "legacy-075", "topic": "2.8", "unit": 2, "stem": "Following a prolonged power outage,the price of flashlights normally increases significantly. If cities had passed laws prohibiting price increases for flashlights, during power outages such laws would most likely", "options": [{"key": "A", "text": "make flashlights more available", "error": "P1"}, {"key": "B", "text": "create a shortage of flashlights", "error": null}, {"key": "C", "text": "shift the demand curve for flashlights to the right", "error": "P1"}, {"key": "D", "text": "shift the supply curve for flashlights to the left", "error": "P1"}], "correct": "B", "explanation": "binding price ceiling", "zh": "有效价格管制才会改变均衡。税收收入等于单位税乘以税后数量；税负取决于相对弹性。", "skill": "policy", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 75, "sourceSection": "2.8"}, {"id": "legacy-079", "topic": "2.8", "unit": 2, "stem": "Assume that in a competitive equilibrium, 1,000 units are sold at $20 per unit. Following the imposition of a $4.00 per unit tax, the new consumer price is $23, and the new equilibrium quantity is 950 units. What are the values of the tax revenue collected and the deadweight loss? Assume linear demand and supply.", "options": [{"key": "A", "text": "Tax revenue $4,000; Deadweight loss $3,000", "error": "P1"}, {"key": "B", "text": "Tax revenue $3,800; Deadweight loss $200", "error": "P1"}, {"key": "C", "text": "Tax revenue $3,800; Deadweight loss $100", "error": null}, {"key": "D", "text": "Tax revenue $3,000; Deadweight loss $100", "error": "P1"}], "correct": "C", "explanation": "Tax revenue = $4 × 950 = $3,800. DWL = 0.5 × $4 × (1,000 − 950) = $100.", "zh": "有效价格管制才会改变均衡。税收收入等于单位税乘以税后数量；税负取决于相对弹性。", "skill": "policy", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 79, "sourceSection": "2.8"}, {"id": "legacy-080", "topic": "2.8", "unit": 2, "stem": "Following the imposition of a $4 per-unit tax in a competitive market, the seller’s after-tax price falls from the original equilibrium price of $12 to $11. Which of the following statements relating to the imposition of the tax is true?", "options": [{"key": "A", "text": "The seller bears 75 percent of the tax burden.", "error": "P1"}, {"key": "B", "text": "The new after-tax equilibrium price is $16.", "error": "P1"}, {"key": "C", "text": "There is no deadweight loss from this tax.", "error": "P1"}, {"key": "D", "text": "The new after-tax equilibrium price is $15.", "error": null}], "correct": "D", "explanation": "Buyer price = seller net price + tax = $11 + $4 = $15. Buyers bear $3 and sellers bear $1.", "zh": "有效价格管制才会改变均衡。税收收入等于单位税乘以税后数量；税负取决于相对弹性。", "skill": "policy", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 80, "sourceSection": "2.8"}, {"id": "legacy-081", "topic": "2.8", "unit": 2, "stem": "Suppose that the market supply curve for shoes is upward sloping and the market demand curve is downward sloping. How will the imposition of a sales tax on shoes affect the consumer surplus, the producer surplus, and the total surplus? Consumer Surplus Producer Surplus Total Surplus", "options": [{"key": "A", "text": "Decrease Decrease Decrease", "error": null}, {"key": "B", "text": "Decrease Increase Increase", "error": "P1"}, {"key": "C", "text": "Decrease Increase Decrease", "error": "P1"}, {"key": "D", "text": "Increase Decrease Decrease", "error": "P1"}], "correct": "A", "explanation": "Use the wedge between buyer price and seller price to identify tax revenue and deadweight loss; compare demand and supply elasticity for burden.", "zh": "有效价格管制才会改变均衡。税收收入等于单位税乘以税后数量；税负取决于相对弹性。", "skill": "policy", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 81, "sourceSection": "2.8"}, {"id": "legacy-082", "topic": "2.9", "unit": 2, "stem": "Country Z is both a producer and an importer of cloth. Which of the following will happen if the government of Country Z imposes a tariff on cloth and the country continues to import some cloth from abroad? Assume the country takes the world price as given.", "options": [{"key": "A", "text": "There will be a decrease in domestic producer surplus.", "error": "P1"}, {"key": "B", "text": "There will be an increase in the quantity demanded for cloth.", "error": "P1"}, {"key": "C", "text": "As the country produces more cloth, there will be an efficiency gain for the economy.", "error": "P1"}, {"key": "D", "text": "There will be a decrease in consumer surplus for domestic consumers.", "error": null}], "correct": "D", "explanation": "Compare domestic price with world price; tariffs raise domestic prices, reduce consumer surplus, increase domestic output, and create deadweight loss.", "zh": "世界价低于国内封闭均衡价时进口；进口关税提高国内价格、增加国内生产并减少消费。", "skill": "policy", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 82, "sourceSection": "2.9"}, {"id": "legacy-083", "topic": "2.9", "unit": 2, "stem": "Country Z is both a producer and an importer of green tea. If country Z imposes a tariff on imports of green tea, which of the following will occur in the domestic market of green tea? Assume the country takes the world price as given.", "options": [{"key": "A", "text": "Consumer surplus will increase.", "error": "P1"}, {"key": "B", "text": "Domestic production will increase.", "error": null}, {"key": "C", "text": "Total consumption of green tea will increase.", "error": "P1"}, {"key": "D", "text": "Producer surplus will decrease.", "error": "P1"}], "correct": "B", "explanation": "Compare domestic price with world price; tariffs raise domestic prices, reduce consumer surplus, increase domestic output, and create deadweight loss.", "zh": "世界价低于国内封闭均衡价时进口；进口关税提高国内价格、增加国内生产并减少消费。", "skill": "policy", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 83, "sourceSection": "2.9"}, {"id": "legacy-084", "topic": "2.9", "unit": 2, "stem": "Country Z has a downward sloping domestic demand curve and an upward sloping domestic supply curve for widgets. In the absence of trade, the domestic price of widgets is P0. Now the country engages in trade, and the price for widgets, Pw, is below the domestic price, P0. Which of the following will occur? Assume the country takes the world price as given.", "options": [{"key": "A", "text": "Country Z will begin exporting widgets.", "error": "P1"}, {"key": "B", "text": "Consumer surplus will decrease in Country Z.", "error": "P1"}, {"key": "C", "text": "Domestic producer surplus will decrease in country Z.", "error": null}, {"key": "D", "text": "Domestic production of widgets in Country Z will increase.", "error": "P1"}], "correct": "C", "explanation": "Compare domestic price with world price; tariffs raise domestic prices, reduce consumer surplus, increase domestic output, and create deadweight loss.", "zh": "世界价低于国内封闭均衡价时进口；进口关税提高国内价格、增加国内生产并减少消费。", "skill": "policy", "target": 75, "source": "Adapted from your existing practice site", "sourceUrl": "https://pjmarymeer-lab.github.io/ap-micro-practice-web/", "sourceId": 84, "sourceSection": "2.9"}];
